function togglePassword(e){const t=document.getElementById(e),a=document.getElementById(e+"-eye");"password"===t.type?(t.type="text",a.classList.remove("fa-eye"),a.classList.add("fa-eye-slash")):(t.type="password",a.classList.remove("fa-eye-slash"),a.classList.add("fa-eye"))}function generateCaptcha(){let e="";for(let t=0;t<6;t++)e+="ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789".charAt(Math.floor(56*Math.random()));document.getElementById("captcha-display").textContent=e,document.getElementById("captcha-answer").value=e,document.getElementById("captcha").value=""}document.addEventListener("DOMContentLoaded",function(){document.getElementById("captcha-display")&&generateCaptcha();const e=document.querySelector('form[action="/signin"]');e&&e.addEventListener("submit",function(e){if(document.getElementById("captcha").value!==document.getElementById("captcha-answer").value)return e.preventDefault(),alert("Captcha verification failed. Please try again."),generateCaptcha(),!1;const t=this.querySelectorAll("[required]");let a=!0;t.forEach(e=>{e.value.trim()?e.classList.remove("is-invalid"):(a=!1,e.classList.add("is-invalid"))}),a||(e.preventDefault(),alert("Please fill in all required fields."))})});